import{_ as t,o as a,c as r,a4 as o}from"./chunks/framework.DpieW3qv.js";const m=JSON.parse('{"title":"CompileRefresh transforms Refresh DTOs into Campaign domain models.","description":"","frontmatter":{},"headers":[],"relativePath":"reference/api/application/compilerefresh.md","filePath":"reference/api/application/compilerefresh.md","lastUpdated":null}'),s={name:"reference/api/application/compilerefresh.md"};function d(i,e,n,c,p,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="compilerefresh-transforms-refresh-dtos-into-campaign-domain-models" tabindex="-1">CompileRefresh transforms Refresh DTOs into Campaign domain models. <a class="header-anchor" href="#compilerefresh-transforms-refresh-dtos-into-campaign-domain-models" aria-label="Permalink to &quot;CompileRefresh transforms Refresh DTOs into Campaign domain models.&quot;">​</a></h1><p>CompileRefresh transforms Refresh DTOs into Campaign domain models.</p><h2 id="architectural-note" tabindex="-1">Architectural Note <a class="header-anchor" href="#architectural-note" aria-label="Permalink to &quot;Architectural Note&quot;">​</a></h2><p>CompileRefresh is a <strong>Domain Service</strong>, not a Use Case. It does not extend BaseUseCase because:</p><ul><li>It performs pure synchronous transformation (DTO → Domain Entity)</li><li>It has no external I/O (no API calls, no async file operations)</li><li>It doesn&#39;t need executeWrapped infrastructure (metrics, retries, error recovery)</li><li>It is called by use cases (ExcelWorkflow, DevWorkflow) as a helper service</li></ul><h2 id="asset-reuse-logic" tabindex="-1">Asset Reuse Logic <a class="header-anchor" href="#asset-reuse-logic" aria-label="Permalink to &quot;Asset Reuse Logic&quot;">​</a></h2><ul><li>LAUNCH: Create new asset ID, register in AssetRegistry</li><li>NO_CHANGE: Look up existing asset ID from registry, reuse it</li><li>UPDATE: Use existing asset ID, update content</li><li>REMOVE: Unregister from AssetRegistry</li></ul><p><strong>Group:</strong> application</p><h2 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>brand</code></td><td><code>Object</code></td><td>BrandContext instance providing services.</td></tr><tr><td><code>brand.fileStore</code></td><td><code>Object</code></td><td>File system store.</td></tr><tr><td><code>brand.assetRegistry</code></td><td><code>Object</code></td><td>Asset registry for reuse lookups.</td></tr><tr><td><code>brand._logger</code></td><td><code>Object</code></td><td>Logger instance; falls back to default logger.</td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="execute-refresh-options-options-skipvalidation" tabindex="-1">execute(refresh, options, options.skipValidation) <a class="header-anchor" href="#execute-refresh-options-options-skipvalidation" aria-label="Permalink to &quot;execute(refresh, options, options.skipValidation)&quot;">​</a></h3><p>Compile a Refresh DTO into a Campaign domain model. Validates the refresh (unless <code>skipValidation</code> is set), builds slots with resolved asset IDs and IPIDs, and returns a Campaign entity.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>refresh</code></td><td><code>RefreshDTO</code></td><td>Parsed refresh DTO with campaign metadata and assetsByType.</td></tr><tr><td><code>options</code></td><td><code>Object</code></td><td>Compile options.</td></tr><tr><td><code>options.skipValidation</code></td><td><code>boolean</code></td><td>Skip Zod schema validation.</td></tr></tbody></table><p><strong>Returns:</strong> <code>Campaign</code> — Compiled Campaign domain entity.</p><h3 id="buildslots-refresh-options" tabindex="-1">_buildSlots(refresh, options) <a class="header-anchor" href="#buildslots-refresh-options" aria-label="Permalink to &quot;_buildSlots(refresh, options)&quot;">​</a></h3><p>Build all slot objects from a Refresh DTO by iterating asset types and zones.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>refresh</code></td><td><code>RefreshDTO</code></td><td>Parsed refresh DTO.</td></tr><tr><td><code>options</code></td><td><code>Object</code></td><td>Compile options forwarded to _createZoneSlot.</td></tr></tbody></table><p><strong>Returns:</strong> <code>Array.&amp;lt;Object&amp;gt;</code> — Array of slot configuration objects.</p><h3 id="createzoneslot-params-params-refresh-params-assettypekey-params-zonekey-params-zonedata-params-hasmultiplezones-params-options" tabindex="-1">_createZoneSlot(params, params.refresh, params.assetTypeKey, params.zoneKey, params.zoneData, params.hasMultipleZones, params.options) <a class="header-anchor" href="#createzoneslot-params-params-refresh-params-assettypekey-params-zonekey-params-zonedata-params-hasmultiplezones-params-options" aria-label="Permalink to &quot;_createZoneSlot(params, params.refresh, params.assetTypeKey, params.zoneKey, params.zoneData, params.hasMultipleZones, params.options)&quot;">​</a></h3><p>Create a single slot object for one asset-type/zone combination. Resolves asset ID (new or reused), builds IPIDs, and assembles the full slot descriptor with context, sync strategy, and category IDs.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>params</code></td><td><code>Object</code></td><td></td></tr><tr><td><code>params.refresh</code></td><td><code>RefreshDTO</code></td><td>Parent refresh DTO.</td></tr><tr><td><code>params.assetTypeKey</code></td><td><code>string</code></td><td>Asset type key (e.g. &quot;HOMEPAGE&quot;).</td></tr><tr><td><code>params.zoneKey</code></td><td><code>string</code></td><td>Zone key (e.g. &quot;ZONE_A&quot;).</td></tr><tr><td><code>params.zoneData</code></td><td><code>Object</code></td><td>Zone object containing items array.</td></tr><tr><td><code>params.hasMultipleZones</code></td><td><code>boolean</code></td><td>Whether the asset type has multiple zones.</td></tr><tr><td><code>params.options</code></td><td><code>Object</code></td><td>Compile options.</td></tr></tbody></table><p><strong>Returns:</strong> <code>Object</code> — Slot configuration object ready for Campaign.fromJSON.</p><h3 id="assettypetopage-assettypekey" tabindex="-1">_assetTypeToPage(assetTypeKey) <a class="header-anchor" href="#assettypetopage-assettypekey" aria-label="Permalink to &quot;_assetTypeToPage(assetTypeKey)&quot;">​</a></h3><p>Map an asset type key to a short page identifier for IPID construction. Falls back to a slugified, lowercased, 8-char truncation of the key.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>assetTypeKey</code></td><td><code>string</code></td><td>Asset type key (e.g. &quot;HOMEPAGE&quot;, &quot;PPH&quot;).</td></tr></tbody></table><p><strong>Returns:</strong> <code>string</code> — Short page code (e.g. &quot;hp&quot;, &quot;pph&quot;, &quot;global&quot;).</p><h3 id="buildipidforitem-item-index-refresh-assettypekey-zonekey" tabindex="-1">_buildIpidForItem(item, index, refresh, assetTypeKey, zoneKey) <a class="header-anchor" href="#buildipidforitem-item-index-refresh-assettypekey-zonekey" aria-label="Permalink to &quot;_buildIpidForItem(item, index, refresh, assetTypeKey, zoneKey)&quot;">​</a></h3><p>Build an IPID (Internal Promotion ID) string for a single line item. Combines brand, page, device, zone, position, promo copy, destination, and date into a standardized tracking identifier.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>item</code></td><td><code>Object</code></td><td>Line item from the Excel zone data.</td></tr><tr><td><code>index</code></td><td><code>number</code></td><td>Zero-based position within the zone.</td></tr><tr><td><code>refresh</code></td><td><code>RefreshDTO</code></td><td>Parent refresh DTO (used for date fallback).</td></tr><tr><td><code>assetTypeKey</code></td><td><code>string</code></td><td>Asset type key (e.g. &quot;HOMEPAGE&quot;).</td></tr><tr><td><code>zoneKey</code></td><td><code>string</code></td><td>Zone key (e.g. &quot;ZONE_A&quot;).</td></tr></tbody></table><p><strong>Returns:</strong> <code>string</code> — Constructed IPID string.</p><h3 id="getdominantaction-items" tabindex="-1">_getDominantAction(items) <a class="header-anchor" href="#getdominantaction-items" aria-label="Permalink to &quot;_getDominantAction(items)&quot;">​</a></h3><p>Determine the dominant action for a set of zone items. Priority order: LAUNCH &gt; HOTFIX &gt; UPDATE &gt; REMOVE &gt; SKIP. Returns SKIP when items is empty or all items are SKIP.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>items</code></td><td><code>Array.&amp;lt;Object&amp;gt;</code></td><td>Zone line items, each with an <code>action</code> field.</td></tr></tbody></table><p><strong>Returns:</strong> <code>string</code> — The dominant ACTION_TYPE constant.</p><h3 id="resolveassetid-params-params-refresh-params-assettypekey-params-zonekey-params-hasmultiplezones-params-action" tabindex="-1">_resolveAssetId(params, params.refresh, params.assetTypeKey, params.zoneKey, params.hasMultipleZones, params.action) <a class="header-anchor" href="#resolveassetid-params-params-refresh-params-assettypekey-params-zonekey-params-hasmultiplezones-params-action" aria-label="Permalink to &quot;_resolveAssetId(params, params.refresh, params.assetTypeKey, params.zoneKey, params.hasMultipleZones, params.action)&quot;">​</a></h3><p>Resolve the asset ID for a slot, deciding whether to reuse an existing registry entry or create a new one. Handles SKIP→LAUNCH bootstrap when no registry entry exists for a skipped asset.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>params</code></td><td><code>Object</code></td><td></td></tr><tr><td><code>params.refresh</code></td><td><code>RefreshDTO</code></td><td>Parent refresh DTO.</td></tr><tr><td><code>params.assetTypeKey</code></td><td><code>string</code></td><td>Asset type key.</td></tr><tr><td><code>params.zoneKey</code></td><td><code>string</code></td><td>Zone key.</td></tr><tr><td><code>params.hasMultipleZones</code></td><td><code>boolean</code></td><td>Whether zone suffix is needed in ID.</td></tr><tr><td><code>params.action</code></td><td><code>string</code></td><td>Raw action from the dominant-action check.</td></tr></tbody></table><p><strong>Returns:</strong> <code>Object</code></p><h3 id="createcampaignid-refresh" tabindex="-1">_createCampaignId(refresh) <a class="header-anchor" href="#createcampaignid-refresh" aria-label="Permalink to &quot;_createCampaignId(refresh)&quot;">​</a></h3><p>Build a deterministic campaign ID from brand, date, and refresh ID. Delegates to Campaign.buildId for the canonical format.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>refresh</code></td><td><code>RefreshDTO</code></td><td>Refresh DTO containing campaign metadata.</td></tr></tbody></table><p><strong>Returns:</strong> <code>string</code> — Campaign ID (e.g. &quot;loft-2026-01-15-r1&quot;).</p><h3 id="createassetid-params-params-refresh-params-assettypekey-params-zonekey-params-hasmultiplezones" tabindex="-1">_createAssetId(params, params.refresh, params.assetTypeKey, params.zoneKey, params.hasMultipleZones) <a class="header-anchor" href="#createassetid-params-params-refresh-params-assettypekey-params-zonekey-params-hasmultiplezones" aria-label="Permalink to &quot;_createAssetId(params, params.refresh, params.assetTypeKey, params.zoneKey, params.hasMultipleZones)&quot;">​</a></h3><p>Build a deterministic content-asset ID from brand, date, refresh ID, asset type, and optionally zone key. Multi-zone assets include a zone suffix; single-zone assets omit it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>params</code></td><td><code>Object</code></td><td></td></tr><tr><td><code>params.refresh</code></td><td><code>RefreshDTO</code></td><td>Refresh DTO.</td></tr><tr><td><code>params.assetTypeKey</code></td><td><code>string</code></td><td>Asset type key.</td></tr><tr><td><code>params.zoneKey</code></td><td><code>string</code></td><td>Zone key.</td></tr><tr><td><code>params.hasMultipleZones</code></td><td><code>boolean</code></td><td>Whether to append zone suffix.</td></tr></tbody></table><p><strong>Returns:</strong> <code>string</code> — Content-asset ID (e.g. &quot;loft-2026-01-15-r1-homepage-zone_a&quot;).</p><h3 id="resolveslotid-assettypekey-zonekey" tabindex="-1">_resolveSlotId(assetTypeKey, zoneKey) <a class="header-anchor" href="#resolveslotid-assettypekey-zonekey" aria-label="Permalink to &quot;_resolveSlotId(assetTypeKey, zoneKey)&quot;">​</a></h3><p>Resolve the SFCC slot ID for an asset type and zone. Checks slot config first, then falls back to brand-level slot mappings, and finally the raw zone key.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>assetTypeKey</code></td><td><code>string</code></td><td>Asset type key.</td></tr><tr><td><code>zoneKey</code></td><td><code>string</code></td><td>Zone key.</td></tr></tbody></table><p><strong>Returns:</strong> <code>string</code> — Resolved SFCC slot ID.</p><h3 id="extractrefreshmeta-refresh" tabindex="-1">extractRefreshMeta(refresh) <a class="header-anchor" href="#extractrefreshmeta-refresh" aria-label="Permalink to &quot;extractRefreshMeta(refresh)&quot;">​</a></h3><p>Extract canonical refresh metadata from a Refresh DTO. Used by callers that need date/id/brand without compiling a full Campaign.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>refresh</code></td><td><code>RefreshDTO</code></td><td>Refresh DTO.</td></tr></tbody></table><p><strong>Returns:</strong> <code>Object</code></p><h3 id="registerassets-campaign-refresh" tabindex="-1">registerAssets(campaign, refresh) <a class="header-anchor" href="#registerassets-campaign-refresh" aria-label="Permalink to &quot;registerAssets(campaign, refresh)&quot;">​</a></h3><p>Register, unregister, or touch assets in the AssetRegistry based on the effective actions computed during compilation.</p><ul><li>LAUNCH (not reused): register the new asset with its items/IPIDs.</li><li>REMOVE: unregister the asset type + zone from the registry.</li><li>UPDATE / HOTFIX: touch the entry (update lastUpdated timestamp). Saves the registry to disk after all mutations.</li></ul><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>campaign</code></td><td><code>Campaign</code></td><td>Compiled Campaign entity.</td></tr><tr><td><code>refresh</code></td><td><code>RefreshDTO</code></td><td>Original refresh DTO (used for date/id metadata).</td></tr></tbody></table><h3 id="getreusesummary-campaign" tabindex="-1">getReuseSummary(campaign) <a class="header-anchor" href="#getreusesummary-campaign" aria-label="Permalink to &quot;getReuseSummary(campaign)&quot;">​</a></h3><p>Compute a summary of asset reuse for a compiled Campaign. Categorizes each asset as new, reused, or bootstrapped (SKIP→LAUNCH fallback).</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>campaign</code></td><td><code>Campaign</code></td><td>Compiled Campaign entity.</td></tr></tbody></table><p><strong>Returns:</strong> <code>Object</code></p><h3 id="getregistry" tabindex="-1">getRegistry() <a class="header-anchor" href="#getregistry" aria-label="Permalink to &quot;getRegistry()&quot;">​</a></h3><p>Return the AssetRegistry instance used by this compiler.</p><p><strong>Returns:</strong> <code>Object</code> — The AssetRegistry instance (or undefined if not injected).</p>',66)])])}const y=t(s,[["render",d]]);export{m as __pageData,y as default};
